#!/usr/bin/env python3
"""Temporary deterministic generator for the visually reviewed POF Batch 2-4 rasters.

The compressed payload is the exact generator source used to create the reviewed
local candidates. It writes to /tmp/pofgen and this wrapper copies only the 15
approved candidate pairs into explicit refined-batch directories. The temporary
generator is removed before the production PR is merged.
"""
from __future__ import annotations

import base64
import zlib
import shutil
from pathlib import Path

PAYLOAD = """"""

ROOT = Path(__file__).resolve().parents[1]
TMP_ROOT = Path("/tmp/pofgen")
TMP_ROOT.mkdir(parents=True, exist_ok=True)

source = zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8")
source = source.replace("/mnt/data", TMP_ROOT.as_posix())
exec(compile(source, "<reviewed-pof-generator>", "exec"), {"__name__": "__main__"})

selected = {
    2: [
        "pof-angle-of-attack-definition-v3",
        "pof-chord-line-v2",
        "pof-four-forces-level-flight-v2",
        "pof-lift-relative-airflow-v2",
        "pof-venturi-bernoulli-v2",
    ],
    3: [
        "pof-angle-of-incidence-v5",
        "pof-centre-of-pressure-v1",
        "pof-relative-airflow-v1",
        "pof-speed-squared-lift-drag-v1",
        "pof-wing-area-lift-drag-v1",
    ],
    4: [
        "pof-aircraft-axes-controls-v1",
        "pof-critical-aoa-stall-v3",
        "pof-stability-types-v1",
        "pof-turn-lift-components-v1",
        "pof-washout-wing-twist-v1",
    ],
}

for batch, stems in selected.items():
    source_dir = TMP_ROOT / ("pof_batch2_v2" if batch == 2 else f"pof_batch{batch}")
    target_dir = ROOT / "public" / "explanation-images" / "principles-of-flight" / f"refined-batch-{batch}"
    target_dir.mkdir(parents=True, exist_ok=True)
    for stem in stems:
        for suffix in (".png", ".webp"):
            src = source_dir / f"{stem}{suffix}"
            if not src.exists():
                raise SystemExit(f"Missing generated asset: {src}")
            shutil.copy2(src, target_dir / src.name)

print("Generated and staged 15 reviewed POF visual pairs")
